  "claim_id": "C057",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C057.component",
    "value": "The field trial's duration, comparison bookings and success rule must be fixed before the trial, using existing-service deadlines.",
    "scope": "Predeclared trial design and evaluation basis; no concrete duration, comparison set or success threshold is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the pretrial specification requirement and deadline basis without specifying their values."
    }
  },
  "signal_basis": {
    "component_id": "C057.signal_basis",
    "value": "Repeated reduction tests preserve lateness in a smaller configuration while specified further removals cease to reproduce it, using fixed deadlines and a common predeclared repetition rule. This supports considering a bounded field trial, whose effectiveness remains to be evaluated.",
    "scope": "Selected-case test results and their transition to prospective field evaluation; no observed field improvement is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
